@Test
public void testManager() throws URISyntaxException, IOException {
    Map<String, LocalResource> resources = new HashMap<>();
    // Test that localization works for regular files and verify that if multiple symlinks are created,
    // they all work
    LocalResource resourceOne = createFile("content-one");
    LocalResource resourceTwo = createFile("content-two");
    resources.put("file-one", resourceOne);
    resources.put("file-two", resourceTwo);
    resources.put("file-three", resourceTwo);
    // Not currently supported, but shouldn't throw an exception...
    resources.put("some-subdir/file-three", resourceTwo);
    TezLocalCacheManager manager = new TezLocalCacheManager(resources, new Configuration());
    try {
        manager.localize();
        Assert.assertEquals("content-one", new String(Files.readAllBytes(Paths.get("./file-one"))));
        Assert.assertEquals("content-two", new String(Files.readAllBytes(Paths.get("./file-two"))));
        Assert.assertEquals("content-two", new String(Files.readAllBytes(Paths.get("./file-three"))));
    } finally {
        manager.cleanup();
    }
    // verify that symlinks were removed
    Assert.assertFalse(Files.exists(Paths.get("./file-one")));
    Assert.assertFalse(Files.exists(Paths.get("./file-two")));
    Assert.assertFalse(Files.exists(Paths.get("./file-three")));
}

@Test
public void testLocalizeRootDirectory() throws URISyntaxException, IOException {
    // default directory
    Map<String, LocalResource> resources = new HashMap<>();
    LocalResource resourceOne = createFile("content-one");
    resources.put("file-one", resourceOne);
    TezLocalCacheManager manager = new TezLocalCacheManager(resources, new Configuration());
    try {
        Assert.assertFalse(Files.exists(Paths.get("./file-one")));
        manager.localize();
        Assert.assertTrue(Files.exists(Paths.get("./file-one")));
    } finally {
        manager.cleanup();
        Assert.assertFalse(Files.exists(Paths.get("./file-one")));
    }
    // configured directory
    Configuration conf = new Configuration();
    conf.set(TezConfiguration.TEZ_LOCAL_CACHE_ROOT_FOLDER, "target");
    manager = new TezLocalCacheManager(resources, conf);
    try {
        // files don't exist at all
        Assert.assertFalse(Files.exists(Paths.get("./file-one")));
        Assert.assertFalse(Files.exists(Paths.get("./target/file-one")));
        manager.localize();
        // file appears only at configured location
        Assert.assertFalse(Files.exists(Paths.get("./file-one")));
        Assert.assertTrue(Files.exists(Paths.get("./target/file-one")));
    } finally {
        manager.cleanup();
        Assert.assertFalse(Files.exists(Paths.get("./target/file-one")));
    }
}

@Test(timeout = 5000)
public // Assign before launch.
void tetSingleSuccessfulTaskFlow() {
    WrappedContainer wc = new WrappedContainer();
    wc.verifyState(AMContainerState.ALLOCATED);
    // Launch request.
    wc.launchContainer();
    wc.verifyState(AMContainerState.LAUNCHING);
    // 1 Launch request.
    wc.verifyCountAndGetOutgoingEvents(1);
    verify(wc.tal).registerRunningContainer(wc.containerID, 0);
    assertNull(wc.amContainer.getCurrentTaskAttempt());
    // Assign task.
    long currTime = wc.appContext.getClock().getTime();
    wc.assignTaskAttempt(wc.taskAttemptID);
    wc.verifyState(AMContainerState.LAUNCHING);
    wc.verifyNoOutgoingEvents();
    assertEquals(wc.taskAttemptID, wc.amContainer.getCurrentTaskAttempt());
    assertTrue(wc.amContainer.getCurrentTaskAttemptAllocationTime() > 0);
    assertTrue(wc.amContainer.getCurrentTaskAttemptAllocationTime() >= currTime);
    // Container Launched
    wc.containerLaunched();
    wc.verifyState(AMContainerState.RUNNING);
    wc.verifyNoOutgoingEvents();
    assertEquals(wc.taskAttemptID, wc.amContainer.getCurrentTaskAttempt());
    // Once for the previous NO_TASKS, one for the actual task.
    verify(wc.chh).register(wc.containerID);
    ArgumentCaptor<AMContainerTask> argumentCaptor = ArgumentCaptor.forClass(AMContainerTask.class);
    verify(wc.tal, times(1)).registerTaskAttempt(argumentCaptor.capture(), eq(wc.containerID), eq(0));
    assertEquals(1, argumentCaptor.getAllValues().size());
    assertEquals(wc.taskAttemptID, argumentCaptor.getAllValues().get(0).getTask().getTaskAttemptID());
    assertEquals(WrappedContainer.taskPriority, argumentCaptor.getAllValues().get(0).getPriority());
    // Attempt succeeded
    wc.taskAttemptSucceeded(wc.taskAttemptID);
    wc.verifyState(AMContainerState.IDLE);
    wc.verifyNoOutgoingEvents();
    assertNull(wc.amContainer.getCurrentTaskAttempt());
    verifyUnregisterTaskAttempt(wc.tal, wc.taskAttemptID, 0, TaskAttemptEndReason.OTHER, null);
    // Container completed
    wc.containerCompleted();
    wc.verifyHistoryStopEvent();
    wc.verifyState(AMContainerState.COMPLETED);
    List<Event> outgoingEvents = wc.verifyCountAndGetOutgoingEvents(1);
    verifyUnOrderedOutgoingEventTypes(outgoingEvents, AMNodeEventType.N_CONTAINER_COMPLETED);
    verifyUnregisterRunningContainer(wc.tal, wc.containerID, 0, ContainerEndReason.COMPLETED, null);
    verify(wc.chh).unregister(wc.containerID);
    assertEquals(1, wc.amContainer.getAllTaskAttempts().size());
    assertFalse(wc.amContainer.isInErrorState());
}

