    verify(rmClient, times(0)).releaseAssignedContainer(eq(container1.getId()));
    LOG.info("Sleeping to ensure that the container has been idled longer " + "than TEZ_AM_CONTAINER_IDLE_RELEASE_TIMEOUT_MAX_MILLIS ");
    Thread.sleep(50l);
    // container should not get released due to min held containers
    verify(rmClient, times(0)).releaseAssignedContainer(eq(container1.getId()));
    taskScheduler.shutdown();
    taskSchedulerManager.close();
}

