@Test(timeout = 5000)
public void testNewAPI_ThroughConf() {
    Configuration conf = new Configuration();
    try {
        MROutput.createConfigBuilder(conf, null).build();
        fail();
    } catch (TezUncheckedException e) {
        assertEquals("no outputFormat setting on Configuration, useNewAPI:true", e.getMessage());
    }
    // wrong output_format class
    conf.set(MRJobConfig.OUTPUT_FORMAT_CLASS_ATTR, org.apache.hadoop.mapred.TextOutputFormat.class.getName());
    try {
        MROutput.createConfigBuilder(conf, null).build();
        fail();
    } catch (IllegalStateException e) {
        assertEquals("outputFormat must be assignable from org.apache.hadoop.mapreduce.OutputFormat", e.getMessage());
    }
    // correct output_format class, but no output_dir specified
    conf.set(MRJobConfig.OUTPUT_FORMAT_CLASS_ATTR, TextOutputFormat.class.getName());
    try {
        MROutput.createConfigBuilder(conf, null).build();
        fail();
    } catch (TezUncheckedException e) {
        assertEquals("OutputPaths must be specified for OutputFormats based " + "on org.apache.hadoop.mapreduce.lib.output.FileOutputFormat " + "or org.apache.hadoop.mapred.FileOutputFormat", e.getMessage());
    }
    conf.set(org.apache.hadoop.mapreduce.lib.output.FileOutputFormat.OUTDIR, "/tmp/output");
    MROutput.createConfigBuilder(conf, null).build();
}

