public void testSendMapCount() throws Exception {
    final List<ShuffleHandler.ReduceMapFileCount> listenerList = new ArrayList<ShuffleHandler.ReduceMapFileCount>();
    final ChannelHandlerContext mockCtx = mock(ChannelHandlerContext.class);
    final Channel mockCh = mock(AbstractChannel.class);
    final ChannelPipeline mockPipeline = Mockito.mock(ChannelPipeline.class);
    // Mock HttpRequest and ChannelFuture
    final FullHttpRequest httpRequest = createHttpRequest();
    final ChannelFuture mockFuture = createMockChannelFuture(mockCh, listenerList);
    final ShuffleHandler.TimeoutHandler timerHandler = new ShuffleHandler.TimeoutHandler();
    // Mock Netty Channel Context and Channel behavior
    Mockito.doReturn(mockCh).when(mockCtx).channel();
    Mockito.when(mockCh.pipeline()).thenReturn(mockPipeline);
    Mockito.when(mockPipeline.get(Mockito.any(String.class))).thenReturn(timerHandler);
    when(mockCtx.channel()).thenReturn(mockCh);
    Mockito.doReturn(mockFuture).when(mockCh).writeAndFlush(Mockito.any(Object.class));
    when(mockCh.writeAndFlush(Object.class)).thenReturn(mockFuture);
    final ShuffleHandler sh = new MockShuffleHandler();
    Configuration conf = new Configuration();
    conf.set(HADOOP_TMP_DIR, TEST_DIR.getAbsolutePath());
    // The Shuffle handler port associated with the service is bound to but not used.
    conf.setInt(ShuffleHandler.SHUFFLE_PORT_CONFIG_KEY, 0);
    sh.init(conf);
    sh.start();
    int maxOpenFiles = conf.getInt(ShuffleHandler.SHUFFLE_MAX_SESSION_OPEN_FILES, ShuffleHandler.DEFAULT_SHUFFLE_MAX_SESSION_OPEN_FILES);
    sh.getShuffle(conf).channelRead(mockCtx, httpRequest);
    assertTrue("Number of Open files should not exceed the configured " + "value!-Not Expected", listenerList.size() <= maxOpenFiles);
    while (!listenerList.isEmpty()) {
        listenerList.remove(0).operationComplete(mockFuture);
        assertTrue("Number of Open files should not exceed the configured " + "value!-Not Expected", listenerList.size() <= maxOpenFiles);
    }
    sh.close();
}

@Test
public void testShuffleHandlerSendsDiskError() throws Exception {
    Configuration conf = new Configuration();
    conf.setInt(ShuffleHandler.SHUFFLE_PORT_CONFIG_KEY, 0);
    DataInputStream input = null;
    MockShuffleHandlerWithFatalDiskError shuffleHandler = new MockShuffleHandlerWithFatalDiskError();
    try {
        shuffleHandler.init(conf);
        shuffleHandler.start();
        String shuffleBaseURL = "http://127.0.0.1:" + shuffleHandler.getConfig().get(ShuffleHandler.SHUFFLE_PORT_CONFIG_KEY);
        URL url = new URL(shuffleBaseURL + "/mapOutput?job=job_12345_1&dag=1&reduce=1&map=attempt_12345_1_m_1_0");
        shuffleHandler.secretManager.addTokenForJob("job_12345_1", new Token<>("id".getBytes(), shuffleHandler.getSecret().getBytes(), null, null));
        HttpConnectionParams httpConnectionParams = ShuffleUtils.getHttpConnectionParams(conf);
        BaseHttpConnection httpConnection = ShuffleUtils.getHttpConnection(true, url, httpConnectionParams, "testFetcher", shuffleHandler.secretManager);
        boolean connectSucceeded = httpConnection.connect();
        Assert.assertTrue(connectSucceeded);
        input = httpConnection.getInputStream();
        httpConnection.validate();
        ShuffleHeader header = new ShuffleHeader();
        header.readFields(input);
        // message is encoded in the shuffle header, and can be checked by fetchers
        Assert.assertEquals(ShuffleHandlerError.DISK_ERROR_EXCEPTION + ": " + MockShuffleHandlerWithFatalDiskError.MESSAGE, header.getMapId());
        Assert.assertEquals(-1, header.getCompressedLength());
        Assert.assertEquals(-1, header.getUncompressedLength());
        Assert.assertEquals(-1, header.getPartition());
    } finally {
        if (input != null) {
            input.close();
        }
        shuffleHandler.close();
    }
}

