@Test(timeout = 20000)
public //Should be interruptible
void testAsyncHttpConnectionInterrupt() throws IOException, InterruptedException, ExecutionException {
    CountDownLatch latch = new CountDownLatch(1);
    HttpConnectionParams params = getConnectionParams();
    AsyncHttpConnection asyncHttpConn = getAsyncHttpConnection(params);
    Future<Void> future = executorService.submit(new Worker(latch, asyncHttpConn, true));
    while (currentThread == null) {
        synchronized (this) {
            wait(100);
        }
    }
    assertTrue("currentThread is still null", currentThread != null);
    //To avoid race to interrupt the thread before connect()
    Thread.sleep(1000);
    //Try interrupting the thread (exception verification happens in the worker itself)
    currentThread.interrupt();
    future.get();
    assertTrue(latch.getCount() == 0);
}

